// Evaluador de longitud y necesidad de división
const output = $input.first().json.output;

// Función para contar caracteres reales (sin marcadores)
function contarCaracteres(texto) {
  return texto.replace(/\[PAUSA_NATURAL\]|\[PAUSA_TEMA\]|\[PAUSA_ESPERA\]/g, '').length;
}

// Determinar el tipo de procesamiento necesario
const longitud = contarCaracteres(output);
const tieneMarcadores = /\[PAUSA_/.test(output);

let resultado = {
  texto: output,
  necesitaDivision: false,
  tipoProcesamiento: 'directo'
};

// AJUSTE: Si tiene marcadores, SIEMPRE dividir
if (tieneMarcadores) {
  resultado.necesitaDivision = true;
  resultado.tipoProcesamiento = 'completo';
} else if (longitud < 250) {
  // Mensaje corto sin marcadores, envío directo
  resultado.tipoProcesamiento = 'directo';
  resultado.partes = {
    parte_1: output.trim(),
    parte_2: "",
    parte_3: ""
  };
} else if (longitud >= 250 && longitud < 500) {
  // Mensaje medio, división simple
  resultado.necesitaDivision = true;
  resultado.tipoProcesamiento = 'simple';
} else {
  // Mensaje largo, división completa
  resultado.necesitaDivision = true;
  resultado.tipoProcesamiento = 'completo';
}

return resultado;

// Procesador final - Unifica output (compatible OpenAI + Anthropic)
let resultado;
const input = $input.first().json;

try {
  if (input.partes) {
    // Viene del bypass directo
    resultado = input.partes;
  } else {
    // Buscar contenido en cualquier formato
    let content = '';

    if (input.message && input.message.content) {
      // Formato OpenAI
      content = input.message.content;
    } else if (input.content && Array.isArray(input.content)) {
      // Formato Anthropic (Claude)
      const textBlock = input.content.find(b => b.type === 'text');
      content = textBlock ? textBlock.text : '';
    } else if (typeof input.content === 'string') {
      content = input.content;
    } else if (input.text) {
      content = input.text;
    }

    if (content) {
      // Limpiar backticks markdown si los hay
      content = content.replace(/```json\s*/gi, '').replace(/```\s*/g, '').trim();

      try {
        resultado = JSON.parse(content);
      } catch (e) {
        // Intentar extraer JSON del texto
        const jsonMatch = content.match(/\{[\s\S]*\}/);
        if (jsonMatch) {
          resultado = JSON.parse(jsonMatch[0]);
        } else {
          resultado = { parte_1: content, parte_2: "", parte_3: "" };
        }
      }
    } else {
      resultado = { parte_1: input.texto || "Error en procesamiento", parte_2: "", parte_3: "" };
    }
  }
} catch (e) {
  resultado = { parte_1: input.texto || "Error en procesamiento", parte_2: "", parte_3: "" };
}

// Limpiar marcadores residuales y markdown en todas las partes
for (let i = 1; i <= 5; i++) {
  const key = `parte_${i}`;
  if (resultado[key]) {
    resultado[key] = resultado[key]
      .replace(/\[PAUSA_NATURAL\]|\[PAUSA_TEMA\]|\[PAUSA_ESPERA\]/g, '')
      .replace(/\*\*(.*?)\*\*/g, '$1')
      .replace(/\*(.*?)\*/g, '$1')
      .trim();
  }
}

return resultado;

